 static void Check(string n,bool pass){checks.Add(n+": "+(pass?"PASS":"FAIL"));}
 static void Tick(){if(!Application.isBatchMode||!EditorApplication.isPlaying)return;if(SessionState.GetBool("Mission01.Test",false)){flow=UnityEngine.Object.FindAnyObjectByType<Mission01Flow>();if(!flow||!flow.initialized)return;SessionState.SetBool("Mission01.Test",false);checks.Clear();Time.timeScale=1;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;flow.UseTestSave(Out+"/Test_Local_Save.json");if(File.Exists(Out+"/Test_Local_Save.json"))File.Delete(Out+"/Test_Local_Save.json");Check("Play Mode instantiated scene",flow.screen==Mission01Flow.Screen.Menu);Check("Missing checkpoint cannot continue",!flow.HasContinue);flow.NewMission();Check("New Mission opens setup",flow.screen==Mission01Flow.Screen.Setup);flow.playerName="x";Check("Short name rejected",!flow.ConfirmSetup());flow.playerName="Test Trainee";Check("Setup opens briefing",flow.ConfirmSetup()&&flow.screen==Mission01Flow.Screen.Briefing);Capture("Briefing_3D_NoUI",flow.menuCamera);flow.BeginLaunch();Check("Briefing opens launch",flow.screen==Mission01Flow.Screen.Launch&&flow.controller.enabled);Check("Distant interaction rejected",!flow.TryBoard());keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();start=flow.player.transform.position;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));began=EditorApplication.timeSinceStartup;step=1;}
 if(step==1){keyboard.MakeCurrent();InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));System.Threading.Thread.Sleep(10);}
 if(step==1&&EditorApplication.timeSinceStartup-began>3.8){InputSystem.QueueStateEvent(keyboard,new KeyboardState());checks.Add("Observed start="+start+" end="+flow.player.transform.position+" frame="+Time.frameCount+" screen="+flow.screen+" updates="+flow.diagnosticTicks+" simulationSeconds="+flow.diagnosticSeconds+" keyboardCurrent="+(Keyboard.current==keyboard)+" w="+keyboard.wKey.isPressed);Check("Input System W moves player",Vector3.Distance(start,flow.player.transform.position)>5);Check("Grounded movement",flow.controller.isGrounded);Check("Rocket proximity completion",flow.TryBoard()&&flow.screen==Mission01Flow.Screen.Complete);Capture("Earth_First_Objective_3D_NoUI",flow.followCamera);Check("Valid saved checkpoint",flow.HasContinue);flow.SetScreen(Mission01Flow.Screen.Menu);Check("Continue restores completion",flow.Continue()&&flow.screen==Mission01Flow.Screen.Complete);File.WriteAllText(Out+"/Test_Local_Save.json","invalid");Check("Corrupt save rejected",!flow.HasContinue);InputSystem.RemoveDevice(keyboard);keyboard=null;step=2;File.WriteAllLines(Out+"/PlayMode_Controlled_Tests.txt",checks);Debug.Log("MISSION01_CONTROLLED_PLAYMODE_COMPLETE");EditorApplication.Exit(checks.Any(x=>x.EndsWith("FAIL"))?1:0);}}
 static void Capture(string name,Camera c){var rt=new RenderTexture(1280,720,24);rt.Create();RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(Out+"/Screenshots/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
